  /** Maximum handoff/snapshot depth accepted by this projection. */
  maxDepth?: number;
  /** Maximum number of retained items across all four sections. */
  maxItems?: number;
  /** Optional per-section item budgets. */
  budgets?: Partial<Record<RecoverySectionName, number>>;
}

export interface RecoveredRecoverySection {
  items: string[];
  kept: number;
  dropped: number;
  truncated: boolean;
}

export interface ContextPressureRecoveryResult {
  status: "recovered" | "unknown" | "depth-exceeded";
  /** This projection is evidence for continuation, never proof that work finished. */
  complete: false;
  depth: number;
  digest: string;
}

export interface ContextPressureRecoverySuccess
  extends ContextPressureRecoveryResult {
  status: "recovered";
  sections: Record<RecoverySectionName, RecoveredRecoverySection>;
  dropped: Record<RecoverySectionName, number>;
  truncated: boolean;
}

export interface ContextPressureRecoveryUnknown extends ContextPressureRecoveryResult {
  status: "unknown";
}

export interface ContextPressureRecoveryDepthExceeded
  extends ContextPressureRecoveryResult {
  status: "depth-exceeded";
}

export type ContextPressureRecoveryOutcome =
  | ContextPressureRecoverySuccess
  | ContextPressureRecoveryUnknown
  | ContextPressureRecoveryDepthExceeded;

const SECTION_NAMES: readonly RecoverySectionName[] = [
  "goals",
  "outstandingWork",
  "dependencies",
  "recentEvidence",
];

const DEFAULT_MAX_DEPTH = 3;
const DEFAULT_MAX_ITEMS = 64;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function firstArray(
  snapshot: Record<string, unknown>,
  ...keys: string[]
): readonly unknown[] | undefined {
  for (const key of keys) {
    const value = snapshot[key];
    if (Array.isArray(value)) return value;
  }
  return undefined;
}

function stableValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stableValue);
  if (isRecord(value)) {
    const result: Record<string, unknown> = {};
    for (const key of Object.keys(value).sort()) {
      result[key] = stableValue(value[key]);
    }
    return result;
  }
  if (typeof value === "number" && !Number.isFinite(value)) return String(value);
  if (typeof value === "bigint") return value.toString();
  return value;
}

function canonicalJson(value: unknown): string {
  return JSON.stringify(stableValue(value));
}

function digestOf(value: unknown): string {
  return createHash("sha256").update(canonicalJson(value)).digest("hex");
}

function itemText(item: unknown): string {
  if (typeof item === "string") return item;
  if (item === undefined) return "";
  if (typeof item === "number" || typeof item === "boolean" || typeof item === "bigint") {
    return String(item);
  }
  return canonicalJson(item);
}

function normalizedDepth(snapshot: Record<string, unknown>): number {
  const raw = snapshot.depth;
  return typeof raw === "number" && Number.isFinite(raw) ? raw : 0;
}

function finiteBudget(value: number | undefined, fallback: number): number {
  if (value === undefined || !Number.isFinite(value)) return fallback;
  return Math.max(0, Math.floor(value));
}

/**
 * Projects a bounded, deterministic recovery summary from a Working Context
 * snapshot. The function is pure: it does not mutate the snapshot, follow links,
 * recurse, start work, or report completion.
 */
export function recoverContextPressure(
  snapshot: WorkingContextRecoverySnapshot | null | undefined,
  options: ContextPressureRecoveryOptions = {}
): ContextPressureRecoveryOutcome {
  const maxDepth = finiteBudget(options.maxDepth, DEFAULT_MAX_DEPTH);
  const depth = normalizedDepth(
    snapshot && isRecord(snapshot) ? (snapshot as Record<string, unknown>) : {}
  );

  if (depth > maxDepth) {
    const body = { status: "depth-exceeded" as const, complete: false as const, depth };
    return { ...body, digest: digestOf(body) };
  }

  if (!snapshot || !isRecord(snapshot)) {
    const body = { status: "unknown" as const, complete: false as const, depth };
    return { ...body, digest: digestOf(body) };
  }

  const rawSections: Record<RecoverySectionName, readonly unknown[] | undefined> = {
    goals: firstArray(snapshot, "goals"),
    outstandingWork: firstArray(snapshot, "outstandingWork", "openWork"),
    dependencies: firstArray(snapshot, "dependencies"),
    recentEvidence: firstArray(snapshot, "recentEvidence", "evidence"),
  };
  const sourceItems = SECTION_NAMES.flatMap((name) => rawSections[name] ?? []);
  if (sourceItems.length === 0) {
    const body = { status: "unknown" as const, complete: false as const, depth };
    return { ...body, digest: digestOf(body) };
  }

  const globalBudget = finiteBudget(options.maxItems, DEFAULT_MAX_ITEMS);
  const sections = {} as Record<RecoverySectionName, RecoveredRecoverySection>;
  let remaining = globalBudget;

  // A deterministic round-robin allocation prevents the first section from
  // silently consuming the whole budget. Every source item is still accounted
  // for by its section's kept and dropped counts.
  const maximumLength = Math.max(
    ...SECTION_NAMES.map((name) => (rawSections[name] ?? []).length)
  );
  const selected = new Map<RecoverySectionName, Set<number>>(
    SECTION_NAMES.map((name) => [name, new Set<number>()])
  );
  for (let round = 0; round < maximumLength && remaining > 0; round += 1) {
    for (const name of SECTION_NAMES) {
      const items = rawSections[name] ?? [];
      if (round >= items.length || remaining === 0) continue;
      const sectionBudget = finiteBudget(options.budgets?.[name], globalBudget);
      if (selected.get(name)!.size >= sectionBudget) continue;
      selected.get(name)!.add(round);
      remaining -= 1;
    }
  }

  for (const name of SECTION_NAMES) {
    const items = rawSections[name] ?? [];
    const indexes = selected.get(name)!;
    const retained = items
      .filter((_item, index) => indexes.has(index))
      .map(itemText);
    const dropped = items.length - retained.length;
    sections[name] = {
      items: retained,
      kept: retained.length,
      dropped,
      truncated: dropped > 0,
    };
  }

  const dropped = {
    goals: sections.goals.dropped,
    outstandingWork: sections.outstandingWork.dropped,
    dependencies: sections.dependencies.dropped,
    recentEvidence: sections.recentEvidence.dropped,
  };
  const truncated = SECTION_NAMES.some((name) => sections[name].truncated);
  const body = {
    status: "recovered" as const,
    complete: false as const,
    depth,
    sections,
    dropped,
    truncated,
  };
  return { ...body, digest: digestOf(body) };
}

export const projectContextPressureRecovery = recoverContextPressure;

